def _azure_event_hub_to_nested(azure_event_hub: AzureEventHub) -> AzureEventHubNested:
    """Convert flat AzureEventHub to nested format."""
    attrs = AzureEventHubAttributes()
    _populate_azure_event_hub_attrs(attrs, azure_event_hub)
